def build(stem, pages):
    doc = Document()
    sec = doc.sections[0]
    sec.page_width, sec.page_height = Inches(8.27), Inches(11.69)
    sec.top_margin = sec.bottom_margin = Inches(.65)
    sec.left_margin = sec.right_margin = Inches(.7)
    for name in ['Normal','Title','Heading 1','Heading 2']:
        st=doc.styles[name]; st.font.name='Calibri'; st.font.color.rgb=RGBColor(0,0,0)
    normal=doc.styles['Normal']; normal.font.size=Pt(10.5)
    normal.paragraph_format.space_after=Pt(6)
    normal.paragraph_format.line_spacing=1.05
    doc.styles['Title'].font.size=Pt(25)
    doc.styles['Heading 1'].font.size=Pt(18)
    doc.styles['Heading 2'].font.size=Pt(12)
    footer=sec.footer.paragraphs[0]; footer.alignment=2
    footer.add_run('SmartSoko  |  ')
    field=OxmlElement('w:fldSimple'); field.set(qn('w:instr'),'PAGE'); footer._p.append(field)
    md=[]
    for idx,(title,sw,blocks) in enumerate(pages):
        if idx: doc.add_page_break()
        doc.add_paragraph(title,'Title' if idx==0 else 'Heading 1')
        p=doc.add_paragraph(sw); p.runs[0].bold=True
        md += ['# '+title,sw,'']
        for enhead,en,swhead,swtxt in blocks:
            doc.add_paragraph(enhead,'Heading 2'); doc.add_paragraph(en)
            p=doc.add_paragraph(); r=p.add_run(swhead+'\n');r.bold=True; p.add_run(swtxt)
            md += ['## '+enhead,en,'', '**'+swhead+'**',swtxt,'']
    doc.core_properties.author='SmartSoko'
    doc.core_properties.title=pages[0][0]
    doc.save(OUT/(stem+'.docx'))
    (OUT/(stem+'.md')).write_text('\n\n'.join(md),encoding='utf-8')

if __name__ == '__main__':
    build('SmartSoko-SME-Manual-English-Swahili',merchant)
    build('SmartSoko-Customer-Guide-English-Swahili',customer)
    print('Created two bilingual booklets and editable text sources')
